/*
 * Zephyr ADC example for nrf52840dk/nrf52840
 *
 * Reads a single ADC channel, converts the raw value to millivolts,
 * and prints the result once per second.
 *
 * The ADC device and channel are obtained from the devicetree using
 * the ADC_DT_SPEC_GET() macro with the node path /zephyr,user.
 */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/printk.h>

/* Devicetree node for the ADC channel (adjust if your DT uses a different node) */
#define ADC_NODE DT_PATH(zephyr_user)

/* Obtain the ADC device/channel specification from the DT */
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(ADC_NODE);

int main(void)
{
    int ret;

    /* Verify that the ADC device is ready */
    if (!device_is_ready(adc_spec.dev)) {
        printk("ADC device not ready\n");
        return 0;
    }

    /* Configure the ADC channel */
    ret = adc_channel_setup_dt(&adc_spec);
    if (ret) {
        printk("Failed to setup ADC channel (err %d)\n", ret);
        return 0;
    }

    /* Sample buffer (single 16‑bit sample) */
    int16_t sample_buf[1];

    /* ADC read sequence */
    struct adc_sequence seq = {
        .channels    = BIT(adc_spec.channel_id),
        .buffer      = sample_buf,
        .buffer_size = sizeof(sample_buf),
        .resolution  = adc_spec.resolution,
    };

    while (1) {
        /* Perform a single ADC conversion */
        ret = adc_read_dt(&adc_spec, &seq);
        if (ret) {
            printk("ADC read error (err %d)\n", ret);
        } else {
            int32_t mv = 0;

            /* Convert the raw sample to millivolts */
            ret = adc_raw_to_millivolts_dt(&adc_spec, sample_buf[0], &mv);
            if (ret) {
                printk("Conversion to millivolts failed (err %d)\n", ret);
            } else {
                printk("ADC reading: %d mV\n", mv);
            }
        }

        k_sleep(K_MSEC(1000));
    }

    /* Unreachable, but required for a non‑void return */
    return 0;
}
